"use strict";

function makeModal(id, className, html, dialogSize = 'modal-lg', shouldOpen = false) {
    let modal = `
		<div class="offcanvas offcanvas-end bg-theme-gray ${className}" tabindex="-1" id="${id}" aria-labelledby="offcanvasRightLabel">
		    ${html}
		</div>
	`;

    $('body').append(modal);
    let $modal = $(document).find(`#${id}`);
    if ($modal.length) {
        let myOffcanvas = $modal[0];
        myOffcanvas.addEventListener('hidden.bs.offcanvas', function () {
            $modal.remove();
        })

        if (shouldOpen) {
            let bsOffcanvas = new bootstrap.Offcanvas(myOffcanvas)
            bsOffcanvas.show();
        }
    }
}

$(document).on('click', '#clear-logs', function (event) {
    event.preventDefault();
    if (confirm('Are you sure you want to clear all logs?')) {
        $(this).closest('form').submit();
    }
});

function AddReadMore() {
    //This limit you can set after how much characters you want to show Read More.
    var carLmt = 150;
    // Text to show when text is collapsed
    var readMoreTxt = " ...read more";
    // Text to show when text is expanded
    var readLessTxt = " read less";

    //Traverse all selectors with this class and manupulate HTML part to show Read More
    $(document).find(".add-read-more").each(function () {
        if ($(this).find(".second-section").length)
            return;

        var allstr = $(this).text();
        if (allstr.length > carLmt) {
            var firstSet = allstr.substring(0, carLmt);
            var secdHalf = allstr.substring(carLmt, allstr.length);
            var strtoadd = firstSet + "<span class='second-section'>" + secdHalf + "</span><span class='read-more'  title='Click to Show More'>" + readMoreTxt + "</span><span class='read-less' title='Click to Show Less'>" + readLessTxt + "</span>";
            $(this).html(strtoadd);
        }
    });

    //Read More and Read Less Click Event binding
    $(".read-more,.read-less").off().on("click", function () {
        $(this).closest(".add-read-more").toggleClass("show-less-content show-more-content");
    });
}

$(document).ready(function () {
    AddReadMore();
});
